"""Klasemen hasil hitungan harus sama dengan klasemen resmi ileague.id.

Data: 61 laga selesai s.d. pekan 7 (diambil 27 Okt 2026) dan klasemen resmi saat itu.
"""
import pandas as pd

from scraper import transform

SCORES = """AREMA_FC>ISENMULANG_KALTENG_FC>4:0>1;BALI_UNITED_FC>PSS_SLEMAN>2:1>1;PERSIK_KEDIRI>DEWA_UNITED_BANTEN_FC>0:1>1;PSIM_YOGYAKARTA>PERSITA>1:1>1;BHAYANGKARA_PRESISI_LAMPUNG_FC>PERSEBAYA_SURABAYA>1:1>1;BORNEO_FC_SAMARINDA>PERSIJA_JAKARTA>0:1>1;JAVA_UNITED_FC>GARUDAYAKSA_FC>1:1>1;MADURA_UNITED_FC>PERSIJAP_JEPARA>2:0>1;PERSIB_BANDUNG>PSM_MAKASSAR>3:1>1;GARUDAYAKSA_FC>PERSIK_KEDIRI>0:2>2;DEWA_UNITED_BANTEN_FC>BHAYANGKARA_PRESISI_LAMPUNG_FC>2:2>2;PERSIJA_JAKARTA>PERSIB_BANDUNG>2:1>2;PSS_SLEMAN>MADURA_UNITED_FC>1:3>2;BALI_UNITED_FC>ISENMULANG_KALTENG_FC>4:1>2;PERSIJAP_JEPARA>BORNEO_FC_SAMARINDA>0:1>2;PERSITA>JAVA_UNITED_FC>3:2>2;PSM_MAKASSAR>AREMA_FC>3:3>2;PERSEBAYA_SURABAYA>PSIM_YOGYAKARTA>1:0>2;BORNEO_FC_SAMARINDA>DEWA_UNITED_BANTEN_FC>1:3>3;AREMA_FC>PERSIK_KEDIRI>1:1>3;MADURA_UNITED_FC>PSIM_YOGYAKARTA>2:1>3;PERSEBAYA_SURABAYA>GARUDAYAKSA_FC>1:1>3;PSM_MAKASSAR>PERSITA>2:2>3;BHAYANGKARA_PRESISI_LAMPUNG_FC>ISENMULANG_KALTENG_FC>2:0>3;PERSIJA_JAKARTA>JAVA_UNITED_FC>1:0>3;BORNEO_FC_SAMARINDA>BALI_UNITED_FC>1:0>3;DEWA_UNITED_BANTEN_FC>PSS_SLEMAN>2:1>3;PERSIJAP_JEPARA>PERSIB_BANDUNG>1:2>3;PERSIK_KEDIRI>MADURA_UNITED_FC>2:0>4;ISENMULANG_KALTENG_FC>PERSEBAYA_SURABAYA>0:1>4;PERSITA>GARUDAYAKSA_FC>2:1>4;AREMA_FC>BHAYANGKARA_PRESISI_LAMPUNG_FC>2:2>4;PSIM_YOGYAKARTA>PERSIJA_JAKARTA>0:4>4;BALI_UNITED_FC>PERSIJAP_JEPARA>6:1>4;JAVA_UNITED_FC>BORNEO_FC_SAMARINDA>2:1>4;PSS_SLEMAN>PSM_MAKASSAR>3:0>4;PERSIB_BANDUNG>DEWA_UNITED_BANTEN_FC>2:2>4;PSIM_YOGYAKARTA>PSM_MAKASSAR>1:2>5;JAVA_UNITED_FC>BALI_UNITED_FC>3:2>5;MADURA_UNITED_FC>BHAYANGKARA_PRESISI_LAMPUNG_FC>3:3>5;PERSIJAP_JEPARA>ISENMULANG_KALTENG_FC>0:1>5;GARUDAYAKSA_FC>AREMA_FC>3:1>5;PERSITA>PERSIJA_JAKARTA>3:2>5;PERSEBAYA_SURABAYA>PSS_SLEMAN>2:2>5;PERSIB_BANDUNG>PERSIK_KEDIRI>1:0>5;ISENMULANG_KALTENG_FC>JAVA_UNITED_FC>1:1>6;BHAYANGKARA_PRESISI_LAMPUNG_FC>PSIM_YOGYAKARTA>1:0>6;DEWA_UNITED_BANTEN_FC>PERSIJAP_JEPARA>2:0>6;BALI_UNITED_FC>GARUDAYAKSA_FC>5:0>6;PERSIJA_JAKARTA>AREMA_FC>5:1>6;PSM_MAKASSAR>PERSEBAYA_SURABAYA>1:0>6;PERSIK_KEDIRI>PSS_SLEMAN>2:1>6;MADURA_UNITED_FC>PERSIB_BANDUNG>1:0>6;ISENMULANG_KALTENG_FC>PSIM_YOGYAKARTA>0:0>7;PERSIJAP_JEPARA>JAVA_UNITED_FC>1:1>7;PERSITA>BALI_UNITED_FC>1:1>7;AREMA_FC>DEWA_UNITED_BANTEN_FC>4:0>7;GARUDAYAKSA_FC>PERSIB_BANDUNG>1:2>7;PERSEBAYA_SURABAYA>MADURA_UNITED_FC>3:1>7;BHAYANGKARA_PRESISI_LAMPUNG_FC>PSM_MAKASSAR>0:0>7;PERSIJA_JAKARTA>PERSIK_KEDIRI>2:1>7"""

OFFICIAL = """1|PERSIJA JAKARTA|7|18;2|DEWA UNITED BANTEN FC|7|14;3|BALI UNITED FC|7|13;4|PERSIB BANDUNG|7|13;5|MADURA UNITED FC|7|13;6|PERSITA|6|12;7|PERSEBAYA SURABAYA|7|12;8|BHAYANGKARA PRESISI LAMPUNG FC|7|11;9|PERSIK KEDIRI|7|10;10|AREMA FC|7|9;11|PSM MAKASSAR|7|9;12|JAVA UNITED FC|7|7;13|BORNEO FC SAMARINDA|5|6;14|GARUDAYAKSA FC|7|5;15|PSS SLEMAN|6|4;16|ISENMULANG KALTENG FC|7|3;17|PSIM YOGYAKARTA|7|2;18|PERSIJAP JEPARA|7|1"""


def _matches():
    rows = []
    for item in SCORES.split(";"):
        h, a, s, w = item.split(">")
        hs, as_ = map(int, s.split(":"))
        rows.append({"match_id": f"{h}-vs-{a}", "matchweek": int(w), "match_date": f"2026-10-{int(w):02d}",
                     "home_team": h.replace("_", " "), "away_team": a.replace("_", " "),
                     "home_score": hs, "away_score": as_, "status": "FT"})
    return pd.DataFrame(rows)


def test_standings_match_official():
    team_rows = transform.team_match_rows(_matches())
    table = transform.standings(team_rows, {"JAVA UNITED FC": -2, "ISENMULANG KALTENG FC": -2})
    got = {r.team: (r.position, r.played, r.points) for r in table.itertuples()}
    for item in OFFICIAL.split(";"):
        pos, team, played, pts = item.split("|")
        assert got[team][1:] == (int(played), int(pts)), team
        assert got[team][0] == int(pos), f"{team}: posisi {got[team][0]} vs resmi {pos}"


def test_standings_by_week_and_clean_sheets():
    team_rows = transform.team_match_rows(_matches())
    by_week = transform.standings_by_week(team_rows)
    assert set(by_week["after_matchweek"]) == set(range(1, 8))
    w1 = by_week[by_week.after_matchweek == 1].set_index("team")
    assert w1.loc["AREMA FC", "position"] == 1  # menang 4-0 di laga pembuka
    cs = transform.team_clean_sheets(team_rows).set_index("team")
    assert cs.loc["PERSIJA JAKARTA", "clean_sheets"] == 3
